using System;using System.Linq;using System.Collections.Generic;using IdleIntelligence.Core;using UnityEngine;using UnityEngine.UI;using UnityEngine.EventSystems;using UnityEngine.InputSystem;
namespace IdleIntelligence.Runtime
{
 public sealed class PrestigeNetworkView:MonoBehaviour,IBeginDragHandler,IDragHandler,IEndDragHandler,IScrollHandler
 {
  public RectTransform World,Viewport;public PrestigeNodeView NodePrefab;public Sprite[] NodeSprites;public Text Ledger;public Button ResetButton;public PrestigePulse Pulse;readonly List<PrestigeNodeView> nodes=new List<PrestigeNodeView>();GameRuntime game;GameObject detail;Transform detailContent;float zoom=(float)PrestigeBalance.ZoomInitial,blockClickUntil;Vector2 touchA,touchB;bool twoTouches;long seenRevision=-1;int lastCount=-1;
  public float Zoom=>zoom;public int NodeCount=>nodes.Count;public bool GestureBlocked=>twoTouches||Time.unscaledTime<blockClickUntil;
  public void Initialize(GameRuntime runtime)
  {
   game=runtime;Pulse.transform.SetParent(GetComponentInParent<Canvas>().transform,false);WorkshopUIFactory.Fill((RectTransform)Pulse.transform);Pulse.gameObject.AddComponent<SafeArea>();for(int i=0;i<PrestigeBalance.Nodes.Length;i++){var d=PrestigeBalance.Nodes[i];var view=Instantiate(NodePrefab,World);view.Id=d.Id;view.name="int-node-"+d.Id;((RectTransform)view.transform).anchoredPosition=new Vector2((float)d.X,(float)d.Y);view.Title.text=d.Id+" · "+d.Name;view.Art.sprite=NodeSprites[i];view.Button.onClick.AddListener(()=>{if(!GestureBlocked)OpenNode(d.Id);});nodes.Add(view);}Home();ResetButton.onClick.AddListener(PerformReset);transform.Find("NetworkTools/ZoomOut").GetComponent<Button>().onClick.AddListener(()=>ZoomAt(zoom/1.15f,Vector2.zero));transform.Find("NetworkTools/ZoomIn").GetComponent<Button>().onClick.AddListener(()=>ZoomAt(zoom*1.15f,Vector2.zero));transform.Find("NetworkTools/Home").GetComponent<Button>().onClick.AddListener(Home);transform.Find("NetworkTools/ReducedPrestigeMotion").GetComponent<Button>().onClick.AddListener(()=>{game.Act(s=>{var n=s.Copy();n.Workshop.reducedMotion=!n.Workshop.reducedMotion;return n;});Pulse.Cancel();});
   for(int i=0;i<6;i++){int branch=i;transform.Find("Branches/Branch"+i).GetComponent<Button>().onClick.AddListener(()=>CenterBranch(branch));}Refresh();
  }
  public void Home(){zoom=(float)PrestigeBalance.ZoomInitial;World.localScale=Vector3.one*zoom;World.anchoredPosition=Vector2.zero;}
  public void CenterBranch(int branch){var p=PrestigeBalance.Nodes.First(n=>n.Branch==branch);World.anchoredPosition=-new Vector2((float)p.X,(float)p.Y)*zoom;}
  public void ZoomAt(float target,Vector2 pivot){float next=Mathf.Clamp(target,(float)PrestigeBalance.ZoomMin,(float)PrestigeBalance.ZoomMax);float ratio=next/zoom;World.anchoredPosition=pivot-(pivot-World.anchoredPosition)*ratio;zoom=next;World.localScale=Vector3.one*zoom;Clamp();}
  public void Pinch(Vector2 oldA,Vector2 oldB,Vector2 nextA,Vector2 nextB){var before=(oldA+oldB)/2;var after=(nextA+nextB)/2;ZoomAt(zoom*Vector2.Distance(nextA,nextB)/Mathf.Max(1,Vector2.Distance(oldA,oldB)),before);World.anchoredPosition+=after-before;Clamp();blockClickUntil=Time.unscaledTime+.25f;}
  void Clamp(){var p=World.anchoredPosition;float extent=1850*zoom;p.x=Mathf.Clamp(p.x,-extent,extent);p.y=Mathf.Clamp(p.y,-extent,extent);World.anchoredPosition=p;}
  public void OnBeginDrag(PointerEventData e){blockClickUntil=Time.unscaledTime+.25f;}
  public void OnDrag(PointerEventData e){if(twoTouches)return;World.anchoredPosition+=e.delta/GetComponentInParent<Canvas>().scaleFactor;Clamp();blockClickUntil=Time.unscaledTime+.25f;}
  public void OnEndDrag(PointerEventData e){blockClickUntil=Time.unscaledTime+.25f;}
  public void OnScroll(PointerEventData e){RectTransformUtility.ScreenPointToLocalPointInRectangle(Viewport,e.position,e.pressEventCamera,out var local);ZoomAt(zoom*Mathf.Pow(1.15f,e.scrollDelta.y),local);}
  void Update()
  {
   if(game==null)return;var touches=Touchscreen.current?.touches.Where(t=>t.press.isPressed).Take(2).ToArray();if(touches!=null&&touches.Length==2){RectTransformUtility.ScreenPointToLocalPointInRectangle(Viewport,touches[0].position.ReadValue(),null,out var a);RectTransformUtility.ScreenPointToLocalPointInRectangle(Viewport,touches[1].position.ReadValue(),null,out var b);if(twoTouches)Pinch(touchA,touchB,a,b);touchA=a;touchB=b;twoTouches=true;blockClickUntil=Time.unscaledTime+.25f;}else twoTouches=false;Refresh();
  }
  void Refresh(){var s=game.State;Ledger.text="INT "+s.Prestige.Free+" · insgesamt "+s.Prestige.Total+"\nNächstes Prestige: +"+PrestigeRules.Claim(s)+" INT · Lauf "+(s.Prestige.resets+1);ResetButton.interactable=game.Writable&&PrestigeRules.Claim(s).CompareTo(ScientificNumber.One)>=0;if(seenRevision==s.Prestige.revision&&lastCount==s.Workshop.nodes.Length)return;seenRevision=s.Prestige.revision;lastCount=s.Workshop.nodes.Length;foreach(var view in nodes){var d=PrestigeBalance.Nodes.First(n=>n.Id==view.Id);bool owned=PrestigeRules.Has(s,d.Id),affordable=s.Prestige.Free.CompareTo(ScientificNumber.From(d.Cost))>=0;view.Price.text=owned?"Aktiv":ScientificNumber.From(d.Cost)+" INT";var c=NetworkWires.Colors[d.Branch];view.Panel.color=owned?c*.62f:affordable?c*.3f:new Color(.07f,.12f,.18f);view.Price.color=owned||affordable?Color.white:new Color(.65f,.72f,.8f);}}
  public void PerformReset(){long ticket=game.State.Prestige.revision;var gain=PrestigeRules.Claim(game.State);if(game.Act(s=>PrestigeRules.Reset(s,ticket))){CloseDetail();Pulse.Play("Neuer Lauf · +"+ScientificNumber.FromData(game.State.Prestige.lastGain)+" INT",game.State.Workshop.reducedMotion);Refresh();}}
  public void Cancel(){Pulse.Cancel();CloseDetail();twoTouches=false;}
  void OnDisable(){Cancel();}void OnDestroy(){if(detail!=null)Destroy(detail);if(Application.isPlaying&&Pulse!=null)Destroy(Pulse.gameObject);}
  public void OpenNode(string id)
  {
   Pulse.Cancel();CloseDetail();var d=PrestigeBalance.Nodes.First(n=>n.Id==id);var s=game.State;detail=WorkshopUIFactory.Node("INTDetails",GetComponentInParent<Canvas>().transform,typeof(Image));WorkshopUIFactory.Fill((RectTransform)detail.transform);var overlay=detail.AddComponent<Canvas>();overlay.overrideSorting=true;overlay.sortingOrder=100;detail.AddComponent<GraphicRaycaster>();detail.GetComponent<Image>().color=new Color(.025f,.045f,.07f,.98f);detail.AddComponent<SafeArea>();
   var panel=WorkshopUIFactory.Vertical("Panel",detail.transform);var pr=(RectTransform)panel.transform;pr.anchorMin=new Vector2(.05f,.05f);pr.anchorMax=new Vector2(.95f,.95f);pr.offsetMin=pr.offsetMax=Vector2.zero;panel.GetComponent<VerticalLayoutGroup>().padding=new RectOffset(10,10,10,10);WorkshopUIFactory.Button("CloseINTDetails",panel.transform,"Schließen",CloseDetail);
   var scroll=WorkshopUIFactory.Node("Scroll",panel.transform,typeof(ScrollRect));scroll.AddComponent<LayoutElement>().flexibleHeight=1;var viewport=WorkshopUIFactory.Node("Viewport",scroll.transform,typeof(RectMask2D));WorkshopUIFactory.Fill((RectTransform)viewport.transform);var content=WorkshopUIFactory.Vertical("Content",viewport.transform);detailContent=content.transform;var cr=(RectTransform)content.transform;cr.anchorMin=new Vector2(0,1);cr.anchorMax=Vector2.one;cr.pivot=new Vector2(.5f,1);cr.offsetMin=cr.offsetMax=Vector2.zero;content.AddComponent<ContentSizeFitter>().verticalFit=ContentSizeFitter.FitMode.PreferredSize;var sr=scroll.GetComponent<ScrollRect>();sr.content=cr;sr.viewport=(RectTransform)viewport.transform;sr.horizontal=false;sr.movementType=ScrollRect.MovementType.Clamped;
   WorkshopUIFactory.Label("NodeName",detailContent,d.Id+" · "+d.Name,19,58);var art=WorkshopUIFactory.Node("NodeArt",detailContent,typeof(Image));WorkshopUIFactory.Size(art,96);art.GetComponent<Image>().sprite=NodeSprites[Array.IndexOf(PrestigeBalance.Nodes,d)];art.GetComponent<Image>().preserveAspect=true;art.GetComponent<Image>().useSpriteMesh=true;WorkshopUIFactory.Label("Description",detailContent,d.Description+"\n\nPreis: "+ScientificNumber.From(d.Cost)+" INT. Verbindungen sind keine Kaufvoraussetzungen.",15,190);
   if(PrestigeBalance.LegacyItemBonuses[d.Id]>0)WorkshopUIFactory.Label("AdditionalItemEffect",detailContent,"Allgemeine Itemboni: +"+(PrestigeBalance.LegacyItemBonuses[d.Id]*100)+" % im gemeinsamen Zusatzpool der aktuellen Regeln.",14,64);
   if(d.Id=="I08")WorkshopUIFactory.Label("DeferredConsumer",detailContent,"Erkenntnis wird gespeichert. Neue KI-Modelle und Axiome folgen im nächsten Abschnitt.",14,64);
   var buy=WorkshopUIFactory.Button("BuyINTNode",detailContent,PrestigeRules.Has(s,id)?"Bereits enthalten / aktiv":"Kaufen · "+ScientificNumber.From(d.Cost)+" INT",()=>{if(game.Act(v=>PrestigeRules.Buy(v,id)))OpenNode(id);});buy.interactable=game.Writable&&!PrestigeRules.Has(s,id)&&s.Prestige.Free.CompareTo(ScientificNumber.From(d.Cost))>=0;
   PrestigeSettings.Build(detailContent,game,id,()=>OpenNode(id));
  }
  public void CloseDetail(){if(detail!=null){detail.SetActive(false);Destroy(detail);detail=null;}}
 }
